dashboard.definition:
{
    "title": "Cisco Catalyst Center",
    "description": "Cisco Catalyst Center device health and AI fabric",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        },
        "input_family": {
            "type": "input.dropdown",
            "title": "Device family",
            "dataSources": {
                "primary": "ds_families"
            },
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "family",
                "defaultValue": "*"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All families"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"DeviceFamily\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"DeviceFamily\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "family": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_families": {
            "type": "ds.search",
            "options": {
                "query": "| tstats count where index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\" by DeviceFamily | fields DeviceFamily",
                "enableSmartSources": true
            },
            "name": "Device families"
        },
        "ds_base": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\" NOT Fabric=\"ai-fabric\"\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| eval site=lower(cat_site)\n| search site=\"$site$\" DeviceFamily=\"$family$\"\n| bin _time span=5m\n| stats avg(HealthScore) as health avg(CpuUtilization) as cpu avg(MemoryUtilization) as mem latest(Reachability) as reach latest(DeviceRole) as role latest(IpAddress) as ip by _time site DeviceFamily DeviceName",
                "enableSmartSources": true
            },
            "name": "Device health (5 min)"
        },
        "ds_latest": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| stats latest(*) as * by site DeviceFamily DeviceName"
            }
        },
        "ds_k_devices": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats dc(DeviceName) as Devices"
            }
        },
        "ds_k_reach": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats count(eval(reach!=\"Reachable\")) as Unreachable"
            }
        },
        "ds_k_health": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(health) as Health"
            }
        },
        "ds_k_cpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(cpu) as CPU"
            }
        },
        "ds_k_mem": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(mem) as Memory"
            }
        },
        "ds_rings": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| stats avg(health) as value dc(DeviceName) as devices by site\n| eval name=site, value=round(value, 1), unit=\"\", min=0, max=10, warn=8, crit=5, better=\"higher\", key=site, detail=devices.\" devices\"\n| table name value unit min max warn crit better detail key"
            }
        },
        "ds_heat_family": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(health) by DeviceFamily"
            }
        },
        "ds_trend": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(health) by site"
            }
        },
        "ds_cpu_trend": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m avg(cpu) by site"
            }
        },
        "ds_band": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| eval Band=case(health >= 8, \"Good (8–10)\", health >= 5, \"Fair (5–7)\", true(), \"Poor (1–4)\") | stats count by Band"
            }
        },
        "ds_devices": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| sort health\n| eval health=round(health, 1), cpu=round(cpu, 1), mem=round(mem, 1)\n| table site DeviceName DeviceFamily role ip health cpu mem reach\n| rename site as Site DeviceName as Device DeviceFamily as Family role as Role ip as \"IP address\" health as Health cpu as \"CPU %\" mem as \"Memory %\" reach as Reachability"
            }
        },
        "ds_fabric": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\" Fabric=\"ai-fabric\"\n| bin _time span=1m\n| stats max(InterfaceUtilization) as util max(BufferUtilization) as buffer min(HealthScore) as health sum(PfcPauseFrames) as pfc sum(EcnMarkedPackets) as ecn sum(OutputDrops) as drops latest(DeviceRole) as role by _time DeviceName",
                "enableSmartSources": true
            },
            "name": "AI fabric (1 min)"
        },
        "ds_fabric_now": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_fabric",
                "query": "| stats latest(role) as Role latest(health) as Health latest(util) as \"Interface util %\" latest(buffer) as \"Buffer util %\" sum(pfc) as \"PFC pause frames\" sum(ecn) as \"ECN marked\" sum(drops) as \"Output drops\" by DeviceName\n| rename DeviceName as Device"
            }
        },
        "ds_fabric_congestion": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_fabric",
                "query": "| timechart span=1m sum(pfc) as \"PFC pause frames\" sum(ecn) as \"ECN marked packets\" sum(drops) as \"Output drops\""
            }
        },
        "ds_fabric_util": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_fabric",
                "query": "| timechart span=1m max(util) as \"Max interface util %\" max(buffer) as \"Max buffer util %\" min(health) as \"Min health\""
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_exec.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_executive",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_factory": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_factory.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_manufacturing",
                        "tokens": [],
