        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_devices"
            },
            "options": {
                "majorColor": "#60a5fa",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_reach"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 5,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 5,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_health"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 5,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 5,
                        "to": 8,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 8,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_cpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 50,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 50,
                        "to": 75,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 75,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_mem"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 60,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 60,
                        "to": 80,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 80,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "coolashaker_studio.health_rings",
            "dataSources": {
                "primary": "ds_rings"
            },
            "options": {
                "decimals": 1,
                "drilldownToken": "site"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "site",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_07": {
            "type": "coolashaker_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat_family"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": true,
                "warn": 8,
                "crit": 5,
                "decimals": 1,
                "drilldownToken": "family"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "family",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "splunk.pie",
            "dataSources": {
                "primary": "ds_band"
            },
            "options": {
                "backgroundColor": "transparent",
                "labelDisplay": "valuesAndPercentage",
                "seriesColors": [
                    "#ffb020",
                    "#34e2a0",
                    "#ff4d6d"
                ],
                "showDonutHole": true
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "seriesColorsByField": {
                    "atlanta": "#22d3ee",
                    "berlin": "#a78bfa",
                    "vienna": "#ffb020",
                    "frankfurt": "#34e2a0",
                    "Atlanta": "#22d3ee",
                    "Berlin": "#a78bfa",
                    "Vienna": "#ffb020",
                    "Frankfurt": "#34e2a0"
                },
                "yAxisMin": 0,
                "yAxisMax": 10,
                "lineWidth": 2
            }
        },
        "viz_10": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_cpu_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "seriesColorsByField": {
                    "atlanta": "#22d3ee",
                    "berlin": "#a78bfa",
                    "vienna": "#ffb020",
                    "frankfurt": "#34e2a0",
                    "Atlanta": "#22d3ee",
                    "Berlin": "#a78bfa",
                    "Vienna": "#ffb020",
                    "Frankfurt": "#34e2a0"
                },
                "lineWidth": 2
            }
        },
        "viz_11": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_devices"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Health": {
                        "rowBackgroundColors": "> table | seriesByName(\"Health\") | rangeValue(range_2)"
                    },
                    "CPU %": {
                        "rowBackgroundColors": "> table | seriesByName(\"CPU %\") | rangeValue(range_3)"
                    },
                    "Memory %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Memory %\") | rangeValue(range_4)"
                    },
                    "Reachability": {
                        "rowBackgroundColors": "> table | seriesByName(\"Reachability\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    }
                ],
                "range_2": [
                    {
                        "to": 5,
                        "value": "#5a1426"
                    },
                    {
                        "from": 5,
                        "to": 8,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 8,
                        "value": "#0d3b2c"
                    }
                ],
                "range_3": [
                    {
                        "to": 50,
                        "value": "#0d3b2c"
